"""Parse a duration string into whole milliseconds. See TASK.md."""

from fractions import Fraction


_UNITS_MS = {"w": 604800000, "d": 86400000, "h": 3600000,
             "m": 60000, "s": 1000, "ms": 1}
_ORDER = {"w": 0, "d": 1, "h": 2, "m": 3, "s": 4, "ms": 5}


def _round_half_up(value):
    """Round a non-negative Fraction to the nearest int, halves away from zero."""
    floor_val = value.numerator // value.denominator
    frac = value - floor_val
    half = Fraction(1, 2)
    if frac > half:
        return floor_val + 1
    if frac < half:
        return floor_val
    return floor_val + 1


def _parse_components(s):
    """Parse the (already sign-stripped, trimmed) body into (num_str, unit, frac)."""
    components = []
    i = 0
    n = len(s)
    while i < n:
        # number: digits, optional fraction with digits on both sides
        start = i
        while i < n and s[i].isdigit():
            i += 1
        num_str = s[start:i]
        if not num_str:
            raise ValueError("missing number")
        frac = False
        if i < n and s[i] == ".":
            frac = True
            i += 1
            fstart = i
            while i < n and s[i].isdigit():
                i += 1
            if i == fstart:
                raise ValueError("fraction needs digits after point")
            num_str = s[start:i]
        # unit: check 'ms' before 'm'
        if i >= n:
            raise ValueError("missing unit")
        if s[i:i + 2] == "ms":
            unit = "ms"
            i += 2
        elif s[i] in "wdhms":
            unit = s[i]
            i += 1
        else:
            raise ValueError("bad unit")
        components.append((num_str, unit, frac))
        # separator: nothing, or exactly one space then a digit
        if i < n:
            if s[i] == " ":
                i += 1
                if i >= n or not s[i].isdigit():
                    raise ValueError("bad separator")
            elif not s[i].isdigit():
                raise ValueError("bad separator")
    if not components:
        raise ValueError("empty")
    return components


def parse_duration(text):
    """Return the duration described by `text` in whole milliseconds. See TASK.md."""
    if not isinstance(text, str):
        raise TypeError("text must be a str")

    trimmed = text.strip()
    if not trimmed:
        raise ValueError("empty input")

    sign = 1
    body = trimmed
    if body[0] == "-":
        sign = -1
        body = body[1:]
    elif body[0] == "+":
        raise ValueError("leading '+' is invalid")
    if not body:
        raise ValueError("empty input")

    components = _parse_components(body)

    # only the last component may carry a fraction
    for _num, _unit, frac in components[:-1]:
        if frac:
            raise ValueError("fraction only allowed on last component")

    # strictly descending unit order, no duplicates
    prev = -1
    for _num, unit, _frac in components:
        idx = _ORDER[unit]
        if idx <= prev:
            raise ValueError("units out of order or repeated")
        prev = idx

    total = Fraction(0)
    for num_str, unit, _frac in components:
        total += Fraction(num_str) * _UNITS_MS[unit]

    return sign * _round_half_up(total)
